from mk import *
from lib import fbd
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 250, "תרשים א: כדור A במסה 0.1 קילוגרם מוחזק בקצה חוט אופקי באורך 80 סנטימטר, וכדור B במסה 0.3 קילוגרם תלוי במנוחה על חוט אנכי באותו אורך. תרשים ב: כדור A משוחרר ונע במסלול מעגלי, ובנקודה S החוט ניתק")
    O = (430, 50)
    g.dot(*O); g.text(O[0] + 6, O[1] - 10, "O₁ O₂", anchor="start")
    g.line(O[0] - 120, O[1], O[0], O[1], width=1.5); g.ball(O[0] - 120, O[1], 9); g.text(O[0] - 136, O[1] + 4, "A", anchor="end")
    g.line(O[0], O[1], O[0], O[1] + 120, width=1.5); g.ball(O[0], O[1] + 128, 11); g.text(O[0], O[1] + 158, "B")
    g.heb(O[0] - 60, 240, "תרשים א")
    O2 = (200, 50)
    g.dot(*O2); g.text(O2[0] + 6, O2[1] - 10, "O₁", anchor="start")
    g.line(O2[0] - 120, O2[1], O2[0], O2[1], width=1.5); g.ball(O2[0] - 120, O2[1], 9); g.text(O2[0] - 136, O2[1] + 4, "A", anchor="end")
    g.path(f"M {O2[0]-120},{O2[1]} A 120 120 0 0 0 {O2[0]+85},{O2[1]+85}", stroke="var(--d-dim)", width=1.5, dash="5 4")
    g.dot(O2[0] + 70, O2[1] + 97); g.text(O2[0] + 60, O2[1] + 120, "S")
    g.heb(O2[0] - 40, 240, "תרשים ב")
    return g

vA = math.sqrt(2 * 10 * 0.8); vB = 2 * 0.1 / 0.4 * vA
E(id="bagrut-1989-q3", year=1989, label="1989 שאלה 3", topic="circular", sub="circ-vertical", diff=4, fig=fig,
  stem=r"כדור $A$ שמסתו $M_1 = 0.1\,\text{kg}$ מוחזק במנוחה בקצה חוט אופקי באורך $\ell = 80\,\text{cm}$, שקשור לנקודה קבועה $O_1$. כדור שני, $B$, שמסתו $M_2 = 0.3\,\text{kg}$, תלוי במנוחה על חוט אנכי באותו אורך, שקשור לנקודה קבועה $O_2$. משחררים את הכדור $A$ ממנוחה, והוא מתנגש התנגשות מצח אלסטית לחלוטין בכדור $B$ (תרשים א). מסת החבלים זניחה, וברגע ההתנגשות שני החבלים אנכיים.",
  parts=[
    P("א", r"מה המהירות, בגודל ובכיוון, של הכדור $A$ רגע לפני ההתנגשות?", num(vA, "m/s"), ["principle"], [
        X(r"החוט ניצב כל הזמן לכיוון התנועה, ולכן הוא לא עושה עבודה. פועל רק כוח הכובד, והאנרגיה המכנית נשמרת. הנקודה הנמוכה היא רמת הייחוס לגובה."),
        S(r"שימור אנרגיה", r"מהמצב האופקי עד הנקודה הנמוכה הכדור יורד באורך החוט. בהתחלה הוא במנוחה", r"M_1 g\ell + 0 = 0 + \tfrac{1}{2} M_1 v^2", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"מחלקים במסה ומבודדים את המהירות", r"המסה מצטמצמת", r"v = \sqrt{2g\ell} = \sqrt{2 \cdot 10 \cdot 0.8} = 4\,\text{m/s}"),
    ], r"$4\,\text{m/s}$, אופקית", key=r"4 m/s"),
    P("ב", r"מה המתיחות בחוט של הכדור $A$ רגע לפני ההתנגשות?", num(3, "N"), ["fbd", "principle"], [
        X(r"בנקודה הנמוכה מרכז המעגל מעל הכדור. בוחרים כחיובי את הכיוון אל המרכז, כלומר כלפי מעלה."),
        D(r"תרשים הכוחות על הכדור A בנקודה הנמוכה", lambda: fbd([("T", 90, 1.25), ("M₁g", -90, 0.45)],
            "תרשים כוחות על הכדור A בנקודה הנמוכה: מתיחות החוט כלפי מעלה, אל המרכז, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה, אל מרכז המעגל",
            positive=90, body="ball", note="המרכז מעל הכדור")),
        S(r"משוואת כוחות בכיוון המרכז", r"בכיוון החיובי המתיחות, ונגדה הכובד. התאוצה היא התאוצה הרדיאלית", r"T - M_1 g = M_1\,\frac{v^2}{\ell}", eq=r"a_R = \frac{v^2}{r}"),
        S(r"מבודדים ומציבים", r"מעבירים את הכובד לאגף השני", r"T = 0.1 \cdot 10 + \frac{0.1 \cdot 4^2}{0.8} = 1 + 2 = 3\,\text{N}"),
    ], r"$3\,\text{N}$", key=r"3 N"),
    P("ג", r"מה הזווית הגדולה ביותר עם האנך שאליה מגיע החוט של הכדור $B$ אחרי ההתנגשות?", num(math.degrees(math.acos(1 - vB ** 2 / 20 / 0.8)), "°"), ["principle", "algebra"], [
        S(r"שימור תנע", r"בהתנגשות הכוחות בין הכדורים פנימיים. הכיוון החיובי הוא כיוון התנועה של A", r"M_1 \cdot 4 + 0 = M_1 u_A + M_2 u_B", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"התנגשות אלסטית", r"במקרה הזה מהירות ההתקרבות שווה למהירות ההתרחקות", r"4 - 0 = -(u_A - u_B)", eq=r"v_A - v_B = -(u_A - u_B)"),
        S(r"פותרים את שתי המשוואות", r"מבודדים את מהירות A מהמשוואה השנייה ומציבים בראשונה", r"u_A = u_B - 4 \;\Rightarrow\; 0.4 = 0.1(u_B - 4) + 0.3\,u_B \;\Rightarrow\; u_B = 2\,\text{m/s}"),
        S(r"הגובה המרבי של B", r"שימור אנרגיה מהנקודה הנמוכה עד השיא, שבו הכדור נעצר לרגע", r"\tfrac{1}{2} M_2 u_B^2 = M_2 g h \;\Rightarrow\; h = \frac{2^2}{2 \cdot 10} = 0.2\,\text{m}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"הזווית", r"הגובה שווה לאורך החוט פחות ההיטל האנכי שלו", r"h = \ell(1 - \cos\beta) \;\Rightarrow\; \cos\beta = 1 - \frac{0.2}{0.8} = 0.75 \;\Rightarrow\; \beta \approx 41.4^\circ"),
    ], r"$\approx 41.4^\circ$", key=r"41.4°"),
    P("ד", r"מסירים את הכדור $B$, ומשחררים שוב את הכדור $A$ ממנוחה כשהחוט אופקי. כשהכדור מגיע לנקודה $S$, הוא ניתק מהחוט (תרשים ב). האם הגובה המרבי שאליו יגיע הכדור אחרי הניתוק גדול מהגובה שממנו שוחרר, קטן ממנו או שווה לו? נמקו.", choice(["גדול", "קטן", "שווה"], 1), ["principle"], [
        S(r"אחרי הניתוק", r"הכדור ממשיך בזריקה משופעת. בשיא נשאר לו רכיב מהירות אופקי, ולכן יש לו אנרגיה קינטית", r"v_x \ne 0 \;\Rightarrow\; E_k > 0"),
        S(r"שימור אנרגיה", r"חלק מהאנרגיה נשאר קינטי, ולכן פחות ממנה הופך לאנרגיה פוטנציאלית", r"mgh_0 = mgh_{\max} + E_k \;\Rightarrow\; h_{\max} < h_0", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"קטן: בשיא יש לכדור מהירות אופקית"),
  ],
  concepts=["שימור אנרגיה", "מתיחות בנקודה הנמוכה", "התנגשות אלסטית", "זריקה משופעת אחרי ניתוק"],
  summary=r"מטוטלת שמכה בכדור שני: מהירות ומתיחות בתחתית, זווית העלייה של הכדור השני, ולמה כדור שניתק לא חוזר לגובה ההתחלתי.",
  review="הנחה שלי.\nהפתרון משתמש בשימור אנרגיה ובשימור תנע, כמו בדף התשובות.\nמה לבדוק: רק לאשר.")
